export const VERIFIED_RESEND_DOMAIN = 'nexus-chat-world.com'
export const DEFAULT_RESEND_FROM = `Nexus Chat <admin@${VERIFIED_RESEND_DOMAIN}>`

// Email verification codes are generated by the server, stored only as a keyed
// hash and checked server-side before a Supabase session is issued. Four digits
// is a deliberate product choice: the short code stays safe because it is
// single-use, expires in ten minutes and is invalidated after a few wrong
// guesses, so an attacker needs many online attempts against a moving target.
export const OTP_CODE_LENGTH = 4
export const OTP_TTL_SECONDS = 600
export const OTP_MAX_ATTEMPTS = 5

const PURPOSE_COPY = {
  signup: {
    subject: 'Your Nexus Chat verification code',
    action: 'verify your email address',
  },
  recovery: {
    subject: 'Your Nexus Chat password reset code',
    action: 'reset your password',
  },
  email: {
    subject: 'Your Nexus Chat sign-in code',
    action: 'sign in',
  },
}

export function resolveResendFrom(value) {
  const raw = String(value || '').trim()
  const address = (raw.match(/<([^>]+)>/)?.[1] || raw).trim().toLowerCase()
  const host = address.split('@')[1] || ''
  return host === VERIFIED_RESEND_DOMAIN ? raw : DEFAULT_RESEND_FROM
}

export function normalizeOtpEmail(value) {
  return String(value || '').trim().toLowerCase()
}

export function otpCodePattern() {
  return new RegExp(`^\\d{${OTP_CODE_LENGTH}}$`)
}

// The stored value is an HMAC over the purpose, address and code, so a leaked
// database row cannot be brute-forced back into a live code without the secret.
export function otpHashPayload({ code, email, purpose }) {
  return `${purpose}:${normalizeOtpEmail(email)}:${String(code || '').trim()}`
}

// The code hash must use a secret dedicated to OTPs. Falling back to the
// service-role key would tie hash secrecy to a widely shared credential, so a
// missing dedicated secret returns an empty string and the endpoints fail closed
// instead of degrading key separation. Both the Vercel function and the Edge
// Function resolve the same secret, so a code issued by one runtime verifies
// against the other.
export function resolveOtpHashSecret(env) {
  const source = env || {}
  return String(source.OTP_HASH_SECRET || source.ADMIN_SESSION_SECRET || '')
}

export function otpEmail({ code, purpose }) {
  const copy = PURPOSE_COPY[purpose] || PURPOSE_COPY.signup
  const text = `Your Nexus Chat code is ${code}. Enter this code to ${copy.action}. It expires in 10 minutes. If you did not request this, ignore this email.`
  const html = `<div style="font-family:Arial,sans-serif;max-width:520px;margin:0 auto;padding:32px;color:#172033"><h1 style="font-size:22px;margin:0 0 16px">Nexus Chat</h1><p style="font-size:16px;line-height:1.5">Use this code to ${copy.action}:</p><p style="font-size:32px;font-weight:700;letter-spacing:6px;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;text-align:center;margin:24px 0">${code}</p><p style="font-size:16px;line-height:1.5">This code expires in 10 minutes. If you did not request this, you can ignore this email.</p></div>`
  return { subject: copy.subject, text, html }
}
